/// <summary>
/// This is an extension class for VendEditInvoice form MetPerformMatching control.
/// </summary>
[ExtensionOf(formControlStr(VendEditInvoice, MetPerformMatching))]
final class METVendEditInvoicePerformMatchingCtrl_Extension
{
}

Method.Source:
    /// <summary>
/// Reset the custom match status on the vendor invoice form.
/// </summary>
public void clicked()
{
    next clicked();

    if (METVendParameters::find().EnableMetcashMatchingLogic)
    {
        //Adding  PO line 
        // Some initial checks outer most checks before main logic,
        // related to PO, 
        //1.PO header status must be exactly received  and required line must be received.
        //2.If any received line/s available in PO lines but not at Invoice lines

        //Main logic - Option 1
        /*
        FormControl ctrl = this;
        FormRun vendEditInvoice_FormRun = ctrl.formRun();
        PurchFormLetter_Invoice purchFormLetter_Invoice =  vendEditInvoice_FormRun.metGetPurchFormLetter();
        if (purchFormLetter_Invoice)
        {
            purchFormLetter_Invoice.showQueryForm(false);
            purchFormLetter_Invoice.
        }*/

        //Invoice matching
        FormControl performMatching = this;
        FormDataSource vendInvInfoTable = performMatching.formRun().dataSource(formDataSourceStr(VendEditInvoice, VendInvoiceInfoTable));
        VendInvoiceInfoTable vendInvoiceInfoTable = vendInvInfoTable.cursor();
        FormRun vendEditInvoice_FormRun = performMatching.formRun();
        PurchFormLetter_Invoice purchFormLetter_Invoice =  vendEditInvoice_FormRun.metGetPurchFormLetter();

        PurchSelectLinesManager purchSelectLinesManager = PurchSelectLinesManager::newPurchSelectLinesManager(vendInvoiceInfoTable.TableRefId);
        purchSelectLinesManager.parmParmId(vendInvoiceInfoTable.ParmId);
        purchSelectLinesManager.metInitPurchSets();

        purchSelectLinesManager.passSets(purchFormLetter_Invoice);

        //Query query = VendInvoiceAutomationCreateLines::buildQueryForPO(_purchIdRangeValue, _specQty);
        //QueryRun queryRun = new QueryRun(query);




        if (!vendInvoiceInfoTable.skipCustomInvoiceMatching() && !vendInvoiceInfoTable.isLandedCostEnabled())
        {
            vendInvInfoTable.executeQuery();
        }
    }
}
